    protected TAMRebateTable copyRebateTable(TAMRebateTable _rebateTable, RefRecId _toRebateDealRecId)
    {
        RefRecId    rebateLineAttributeRule;

        rebateLineAttributeRule = _rebateTable.PricingRuleLine;

        TAMRebateTable copiedRebateTable = next copyRebateTable(_rebateTable, _toRebateDealRecId);

        copiedRebateTable = TAMRebateCopy::METCopyRebateTableAttributeExcludeForPayment(copiedRebateTable.RebateId, rebateLineAttributeRule);

        return copiedRebateTable;
    }
